    def getGoodIndices(self, variables, target):
        """
        :type variables: List[List[int]]
        :type target: int
        :rtype: List[int]
        """
        def calculate_value(a, b, c, m):
            return ((a ** b) % 10) ** c % m

        good_indices = []
        for i, (a, b, c, m) in enumerate(variables):
            if calculate_value(a, b, c, m) == target:
                good_indices.append(i)
        return good_indices
